    temp_accX = Taylor1(identity(constant_term(zero_q_1)), order)
    temp_accY = Taylor1(identity(constant_term(zero_q_1)), order)
    temp_accZ = Taylor1(identity(constant_term(zero_q_1)), order)
    P_2_sin_ϕ = Array{S}(undef, N)
